const icons={compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',heart:'<path d="M20.8 4.8a5.5 5.5 0 0 0-7.8 0L12 6l-1-1.2a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.4a5.5 5.5 0 0 0 0-7.8z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',sliders:'<path d="M4 7h5m4 0h7M4 17h9m4 0h3"/><circle cx="11" cy="7" r="2"/><circle cx="15" cy="17" r="2"/>',x:'<path d="m6 6 12 12M18 6 6 18"/>',down:'<path d="M12 4v16m-6-6 6 6 6-6"/>',undo:'<path d="M3 10a9 9 0 1 1 2 8M3 3v7h7"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.sparkles}</svg>`;
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={choices:{},history:[],ratings:{},preferences:{}},storageOK=true;
try{const s=JSON.parse(localStorage.getItem('cineclub-v1')||'null');if(s&&s.choices&&Array.isArray(s.history)){state.choices=Object.fromEntries(Object.entries(s.choices).filter(([id,v])=>movies.some(m=>m.id===Number(id))&&['like','dislike','watch','skip','uninterested'].includes(v)));state.history=s.history.filter(h=>movies.some(m=>m.id===h.id)&&['like','dislike','watch','skip','uninterested'].includes(h.action));state.ratings=Object.fromEntries(Object.entries(s.ratings||{}).filter(([id,r])=>movies.some(m=>m.id===Number(id))&&Number.isFinite(r)&&r>=.5&&r<=5&&Number.isInteger(r*2)&&['like','dislike'].includes(state.choices[id])));state.preferences=DataFiles.cleanPreferences(s.preferences||{});}}catch{storageOK=false;}
let page='discover',filter={genre:'',min:'',max:'',duration:'',provider:'',...(state.preferences.filters||{})},busy=false,toastTimer,gridLimit=24;
const labels={like:'Mi piace',dislike:'Non mi piace',watch:'Voglio vederlo',uninterested:'Non mi interessa',skip:'Saltato in precedenza'};
function persist(){state.preferences={filters:{...filter},filtersOpen:$('#filter-toggle').classList.contains('open')};try{localStorage.setItem('cineclub-v1',JSON.stringify(state));Account.changed();}catch{storageOK=false;toast('Memoria non disponibile: le scelte valgono per questa sessione.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function paintIcons(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function passes(m){return (!filter.genre||m.genres.includes(filter.genre))&&(!filter.min||m.year&&m.year>=Number(filter.min))&&(!filter.max||m.year&&m.year<=Number(filter.max))&&(!filter.duration||(m.minutes?m.minutes<Number(filter.duration):m.runtimeUpperBound&&m.runtimeUpperBound<Number(filter.duration)))&&(!filter.provider||m.providers?.some(p=>p.name===filter.provider));}
function likes(){return movies.filter(m=>state.choices[m.id]==='like');}
function ranked(){const votes=movies.filter(m=>['like','dislike'].includes(state.choices[m.id]));return movies.filter(m=>!['like','dislike','uninterested'].includes(state.choices[m.id])&&passes(m)).map(m=>{let score=0,best=null,bestScore=0,bestReason='';for(const v of votes){const shared=m.genres.filter(g=>v.genres.includes(g));const sameDirector=Boolean(m.director)&&m.director===v.director;const sameActor=m.actors.some(a=>v.actors.includes(a));const sameDecade=Boolean(m.year&&v.year)&&Math.floor(m.year/10)===Math.floor(v.year/10);const linked=m.similarTo?.includes(v.id);const strength=(linked?6:0)+shared.length*3+(sameDirector?7:0)+(sameActor?4:0)+(sameDecade?1:0);score+=strength*(state.choices[v.id]==='like'?1:-.75);if(state.choices[v.id]==='like'&&strength>bestScore){best=v;bestScore=strength;bestReason=linked?`Simile a ${v.title}, secondo TMDB`:sameDirector?`Stesso regista di ${v.title}`:sameActor?`Un volto che hai amato in ${v.title}`:shared.length?`Come ${v.title}, un film ${shared[0].toLowerCase()}`:`Dallo stesso decennio di ${v.title}`;}}return {m,score,reason:best?bestReason:'Un titolo da cui iniziare a scoprire i tuoi gusti'};}).sort((a,b)=>b.score-a.score||(b.m.rating||0)-(a.m.rating||0));}
function movieYear(m){return m.year||'Anno n.d.';}
function movieDuration(m){return m.minutes?`${m.minutes} min`:'Durata n.d.';}
function movieRating(m){return m.rating?`★ ${Number(m.rating).toFixed(1)}`:'';}
function movieSummary(m){return m.description||(m.director?`Un film di ${m.director}.`:'Apri i dettagli per conoscere questo film.');}
function poster(m,cls=''){return m.poster?`<img class="${cls}" src="${esc(m.poster)}" alt="Locandina di ${esc(m.title)}" loading="lazy" draggable="false" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'cover-placeholder',textContent:this.alt.replace('Locandina di ', '')}))">`:`<div class="cover-placeholder ${cls}" style="background-color:${m.color}">${esc(m.title)}</div>`;}
function recItem(r){return `<div class="rec-item"><button class="rec-poster" data-details="${r.m.id}" aria-label="Dettagli di ${esc(r.m.title)}">${poster(r.m)}</button><div class="rec-info"><h4>${esc(r.m.title)}</h4><p>${movieYear(r.m)} <span>·</span> ${esc(r.m.genres[0]||'Genere n.d.')} <span>·</span> ${movieDuration(r.m)}</p><p class="rec-reason">${icon('sparkles')}${esc(r.reason)}</p></div><button class="mini-save" data-save="${r.m.id}" aria-label="${state.choices[r.m.id]==='watch'?'Rimuovi dalla':'Aggiungi alla'} watchlist">${icon(state.choices[r.m.id]==='watch'?'check':'bookmark')}</button></div>`;}
function goto(p){page=p;gridLimit=24;render();}
function choose(id,action,animate=false){if(busy||(Account.user&&!Account.ready))return;const m=movies.find(m=>m.id===id);if(!m)return;const commit=()=>{state.history.push({id,action,previous:state.choices[id]??null,previousRating:state.ratings[id]??null});state.choices[id]=action;delete state.ratings[id];persist();if(action==='like'){m.tmdbDetailed=false;TMDB.enrich(m);}busy=false;render();toast(action==='watch'?`${m.title} aggiunto alla watchlist`:action==='uninterested'?'Film escluso dai consigli':`${labels[action]} · ${m.title}`);};if(animate&&$('.movie-card')){busy=true;const card=$('.movie-card');const transforms={like:'translateX(350px) rotate(20deg)',dislike:'translateX(-350px) rotate(-20deg)',watch:'translateY(-350px)',uninterested:'translateY(350px)'};card.style.transform=transforms[action];card.style.opacity='0';setTimeout(commit,220);}else commit();}
function undo(){if(Account.user&&!Account.ready)return;const h=state.history.pop();if(!h)return;if(h.previous===null||h.previous===undefined)delete state.choices[h.id];else state.choices[h.id]=h.previous;if(h.previousRating!=null)state.ratings[h.id]=h.previousRating;else delete state.ratings[h.id];persist();render();toast('Ultima scelta annullata');}
function removeWatch(id){if(Account.user&&!Account.ready)return;const prev=state.choices[id];state.history.push({id,action:'skip',previous:prev,previousRating:state.ratings[id]??null});delete state.choices[id];delete state.ratings[id];persist();render();toast('Rimosso dalla watchlist');}
function rightColumn(){const voted=movies.filter(m=>m.id<=25&&state.choices[m.id]).length;const recs=ranked().filter(r=>!state.choices[r.m.id]).slice(0,3);return `<aside class="right-column"><div class="onboarding"><div class="onboarding-top"><span>${icon('sparkles')}${voted>=25?'Il tuo cinema prende forma':'Facciamo conoscenza'}</span><small>${voted} / 25</small></div><p>${voted>=25?'Hai completato il percorso iniziale. Continua a scegliere per affinare i consigli.':'25 film, tanti mondi diversi.<br>Qualche swipe e iniziamo a capirti.'}</p><div class="progress"><span style="width:${voted/25*100}%"></span></div></div><section><div class="recommend-title"><h3>Potrebbe scattare qualcosa</h3><button data-goto="recommend">Tutti ↗︎</button></div><p class="subtitle">${likes().length?'Scelti seguendo i tuoi gusti.':'I primi spunti, prima dei tuoi like.'}</p>${recs.map(recItem).join('')||'<p class="subtitle">Nessun film con questi filtri. Prova ad allargarli.</p>'}<div class="taste-teaser"><div class="taste-orb">✳</div><div><b>Il tuo gusto è unico.</b><p>Ogni swipe ci aiuta a conoscerlo.</p></div></div></section></aside>`;}
function discover(){const priority=m=>m.id<=25?0:m.source==='tmdb'?1:m.source==='starter'?2:3;const queue=movies.filter(m=>!state.choices[m.id]&&passes(m)).sort((a,b)=>priority(a)-priority(b));const m=queue[0];return `<div class="discovery"><section class="swipe-zone"><div class="section-label"><span>UN FILM ALLA VOLTA</span><span class="chip">${queue.length} da scoprire</span></div>${m?`<div class="stack"><article class="movie-card" data-id="${m.id}"><div class="poster-fallback" style="background-color:${m.color}">${esc(m.title)}</div>${poster(m)}<div class="card-top"><span class="card-tag">${m.id<=25?'CONOSCIAMOCI MEGLIO':'ALLARGA I TUOI ORIZZONTI'}</span><button class="info-button" data-details="${m.id}" aria-label="Dettagli del film">i</button></div><div class="swipe-label"></div><div class="card-info"><h2>${esc(m.title)}</h2><div class="card-meta"><span>${movieYear(m)}</span><span>·</span><span>${movieDuration(m)}</span><span class="rating">★ ${m.rating?Number(m.rating).toFixed(1):'—'}</span></div><div class="genre-pills">${m.genres.map(g=>`<span>${esc(g)}</span>`).join('')}${m.director?`<span>${esc(m.director)}</span>`:''}</div><p>${esc(movieSummary(m))}</p></div></article></div><div class="action-bar"><button class="action dislike" data-choice="dislike"><span class="action-circle">${icon('x')}</span>Non mi piace</button><button class="action skip" data-choice="uninterested"><span class="action-circle">${icon('down')}</span>Non mi interessa</button><button class="action like" data-choice="like"><span class="action-circle">${icon('heart')}</span>Mi piace</button><button class="action watch" data-choice="watch"><span class="action-circle">${icon('bookmark')}</span>Voglio vederlo</button></div><p class="swipe-hint">← Non mi piace &nbsp; · &nbsp; ↓ Non mi interessa &nbsp; · &nbsp; ↑ Watchlist &nbsp; · &nbsp; Mi piace →</p>`:empty(Object.values(filter).some(Boolean)?'Nessun film con questi filtri':TMDB.loading?'Carico nuovi film…':TMDB.hasMore(filter)?'Il prossimo film ti aspetta':'Hai esplorato i film disponibili',Object.values(filter).some(Boolean)?'Prova un altro genere o un periodo più ampio.':TMDB.connected?'Carica altri film da TMDB o riconsidera quelli esclusi.':'Collega TMDB per continuare a scoprire nuovi film, oppure riconsidera quelli esclusi.',Object.values(filter).some(Boolean)?'reset':TMDB.connected&&TMDB.hasMore(filter)?'load':TMDB.connected?'revisit':'connect',Object.values(filter).some(Boolean)?'Azzera filtri':TMDB.connected&&TMDB.hasMore(filter)?'Carica altri film':TMDB.connected?'Riconsidera i film esclusi':'Collega TMDB')}<div class="undo-row"><button id="undo" ${!state.history.length?'disabled':''}>${icon('undo')}Annulla ultimo swipe</button><span>Il tuo istinto, senza pressione.</span></div></section>${rightColumn()}</div>`;}
function empty(title,desc,action,label){return `<div class="empty"><div class="taste-orb" style="margin:auto">✳</div><h2>${title}</h2><p>${desc}</p>${action?`<button class="primary" data-empty="${action}">${label} →</button>`:''}</div>`;}
function gridCard(m,reason,watch=false){return `<article class="grid-card"><div class="grid-image" data-details="${m.id}" tabindex="0" role="button" aria-label="Dettagli di ${esc(m.title)}">${poster(m)}</div><div class="grid-body"><h3>${esc(m.title)}</h3><p>${movieYear(m)} · ${esc(m.genres[0]||'Genere n.d.')} · ${movieDuration(m)}</p>${reason?`<p class="rec-reason">✳ ${esc(reason)}</p>`:''}<div class="grid-buttons">${watch?`<button data-rate="${m.id}" data-value="like">♥ Visto, mi piace</button><button data-remove="${m.id}">Rimuovi</button>`:`<button data-save="${m.id}">${state.choices[m.id]==='watch'?'✓ In watchlist':'+ Watchlist'}</button><button data-details="${m.id}">Dettagli ↗︎</button>`}</div></div></article>`;}
function moreGrid(total){return total>gridLimit?`<button id="more-grid" class="primary">Mostra altri film (${total-gridLimit} rimanenti) →</button>`:'';}
function recommend(){const r=ranked().filter(r=>!state.choices[r.m.id]||state.choices[r.m.id]==='watch');return `${!likes().length?'<div class="onboarding"><p style="margin:0">Esprimi qualche like nella sezione Scopri: questi primi suggerimenti diventeranno consigli basati sui tuoi gusti.</p></div>':''}${r.length?`<div class="grid">${r.slice(0,gridLimit).map(x=>gridCard(x.m,x.reason)).join('')}</div>${moreGrid(r.length)}`:empty('Nessun consiglio disponibile','Prova ad allargare i filtri o riconsidera i film esclusi.','discover','Torna a scoprire')}`;}
function watchlist(){const ms=movies.filter(m=>state.choices[m.id]==='watch'&&passes(m));return ms.length?`<div class="section-label">${ms.length} FILM PER LA TUA PROSSIMA SERATA</div><div class="grid">${ms.slice(0,gridLimit).map(m=>gridCard(m,'',true)).join('')}</div>${moreGrid(ms.length)}`:empty('La tua prossima serata inizia qui','Fai swipe in su sui film che ti incuriosiscono.<br>Li ritroverai tutti nella tua watchlist.','discover','Scopri un film');}
function taste(){const liked=likes(),disliked=movies.filter(m=>state.choices[m.id]==='dislike');const counts={};liked.forEach(m=>m.genres.forEach(g=>counts[g]=(counts[g]||0)+1));const entries=Object.entries(counts).sort((a,b)=>b[1]-a[1]);return `<div class="stats"><div class="stat"><b>${liked.length}</b><span>Film che ami</span></div><div class="stat"><b>${disliked.length}</b><span>Non fanno per te</span></div><div class="stat"><b>${Object.values(state.choices).filter(v=>v==='watch').length}</b><span>Da vedere</span></div></div><div class="taste-chart"><h3>Le tue affinità</h3>${entries.length?entries.map(([g,c])=>`<div class="taste-bar"><span>${g}</span><div><i style="width:${c/entries[0][1]*100}%"></i></div><span>${c} ♥</span></div>`).join(''):'<p class="subtitle">I tuoi generi preferiti appariranno qui dopo i primi like.</p>'}</div><button class="import mobile-import" id="taste-import">${icon('upload')} Importa i tuoi voti da Letterboxd</button>${DataFiles.panel()}<h3>Le tue scelte</h3>${movies.filter(m=>state.choices[m.id]).map(m=>`<div class="history-item"><button data-details="${m.id}">${esc(m.title)} <span>(${movieYear(m)})</span></button><span>${labels[state.choices[m.id]]}</span><button data-correct="${m.id}">Correggi</button></div>`).join('')||'<p class="subtitle">Ancora nessuna scelta. Il primo film ti aspetta.</p>'}`;}
function render(){const titles={discover:['Scopri','Il prossimo film?<br><em>Segui il tuo istinto.</em>','Tu scegli. Noi impariamo a conoscere il tuo cinema.'],recommend:['Per te','Il tuo cinema.<br><em>Il tuo prossimo colpo di fulmine.</em>','Consigli che cambiano insieme ai tuoi gusti.'],watchlist:['Watchlist','Non perderli di vista.<br><em>La tua watchlist.</em>','Quei film che meritano una serata tutta per loro.'],taste:['I tuoi gusti','Ogni scelta racconta<br><em>il tuo cinema.</em>','Generi, preferenze e tutti i film che hai scelto.']};$('#breadcrumb').textContent=titles[page][0];$('#page-title').innerHTML=titles[page][1];$('#page-description').textContent=titles[page][2];document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#watch-count').textContent=Object.values(state.choices).filter(c=>c==='watch').length;$('#filter-toggle').hidden=page==='taste';$('#filters').hidden=page==='taste'||!$('#filter-toggle').classList.contains('open');$('#content').innerHTML=({discover,recommend,watchlist,taste}[page])();bindContent();if(page==='discover'){bindSwipe();const card=$('.movie-card');if(card)TMDB.enrich(movies.find(m=>m.id===Number(card.dataset.id)));maybeLoadMore();}updateCatalogStatus();}
function bindContent(){document.querySelectorAll('[data-details]').forEach(b=>{b.onclick=()=>details(Number(b.dataset.details));if(b.tagName!=='BUTTON')b.onkeydown=e=>{if(e.key==='Enter')b.click();};});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(Number($('.movie-card').dataset.id),b.dataset.choice,true));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>state.choices[b.dataset.save]==='watch'?removeWatch(Number(b.dataset.save)):choose(Number(b.dataset.save),'watch'));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeWatch(Number(b.dataset.remove)));document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.rate),b.dataset.value));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>goto(b.dataset.goto));document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>details(Number(b.dataset.correct),true));document.querySelectorAll('[data-empty]').forEach(b=>b.onclick=()=>{if(b.dataset.empty==='reset')resetFilters();else if(b.dataset.empty==='connect')openTMDB();else if(b.dataset.empty==='load')TMDB.more({...filter});else if(b.dataset.empty==='revisit'){Object.keys(state.choices).forEach(id=>{if(['skip','uninterested'].includes(state.choices[id])){delete state.choices[id];delete state.ratings[id];}});persist();render();}else goto('discover');});if($('#more-grid'))$('#more-grid').onclick=()=>{gridLimit+=24;render();};if($('#undo'))$('#undo').onclick=undo;if($('#taste-import'))$('#taste-import').onclick=()=>$('#csv-input').click();DataFiles.bindPanel();}
function details(id,correct=false){const m=movies.find(m=>m.id===id);if(!m)return;TMDB.enrich(m);$('#details-content').innerHTML=`${poster(m,'detail-image')}<h2>${esc(m.title)}</h2><p>${movieYear(m)} · ${movieDuration(m)} · ★ ${m.rating?Number(m.rating).toFixed(1):'—'} · ${m.genres.map(esc).join(', ')}</p><p>${esc(movieSummary(m))}</p><p>Regia: <b>${esc(m.director||'Non disponibile')}</b><br>Cast: ${m.actors.length?m.actors.map(esc).join(', '):'Non disponibile'}</p><a class="detail-link" href="https://www.justwatch.com/it/ricerca?q=${encodeURIComponent(m.title)}" target="_blank" rel="noopener">Dove vederlo · Cerca su JustWatch ↗︎</a><p class="muted">${m.providers===null?'Disponibilità in abbonamento non ancora verificata. Cerca su JustWatch.':m.providers.length?`Abbonamenti in Italia: ${m.providers.map(p=>esc(p.name)).join(', ')}. Verifica prima di guardare.`:'TMDB non indica abbonamenti disponibili in Italia per questo film. Controlla JustWatch per altre opzioni.'}</p><div class="grid-buttons">${Object.entries(labels).filter(([a])=>a!=='skip').map(([a,l])=>`<button data-detail-action="${a}" data-movie-id="${m.id}">${esc(l)}</button>`).join('')}</div>`;if(!$('#details').open)$('#details').showModal();document.querySelectorAll('[data-detail-action]').forEach(b=>b.onclick=()=>{$('#details').close();choose(id,b.dataset.detailAction);});}
function bindSwipe(){const card=$('.movie-card');if(!card)return;let start=null;card.onpointerdown=e=>{if(e.target.closest('button')||busy)return;start={x:e.clientX,y:e.clientY,id:e.pointerId};card.setPointerCapture(e.pointerId);card.classList.add('dragging');};card.onpointermove=e=>{if(!start)return;const x=e.clientX-start.x,y=e.clientY-start.y;card.style.transform=`translate(${x}px,${y}px) rotate(${x/22}deg)`;const action=Math.abs(x)>Math.abs(y)?(x>0?'like':'dislike'):(y<0?'watch':'uninterested');const stamp=card.querySelector('.swipe-label');stamp.textContent=labels[action];stamp.style.opacity=Math.min(Math.max(Math.abs(x),Math.abs(y))/100,1);};const finish=e=>{if(!start)return;const x=e.clientX-start.x,y=e.clientY-start.y;start=null;card.classList.remove('dragging');if(Math.max(Math.abs(x),Math.abs(y))>75){choose(Number(card.dataset.id),Math.abs(x)>Math.abs(y)?(x>0?'like':'dislike'):(y<0?'watch':'uninterested'),true);}else{card.style.transform='';card.querySelector('.swipe-label').style.opacity=0;}};card.onpointerup=finish;card.onpointercancel=()=>{start=null;card.classList.remove('dragging');card.style.transform='';card.querySelector('.swipe-label').style.opacity=0;};}
function resetFilters(){gridLimit=24;filter={genre:'',min:'',max:'',duration:'',provider:''};['genre-filter','year-min','year-max','duration-filter','provider-filter'].forEach(id=>$('#'+id).value='');$('#filter-count').textContent='';persist();render();scheduleTMDBLoad();}
// CSV parser supports commas, newlines and doubled quotes inside quoted fields.
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(c=>c.trim()))rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(c=>c.trim()))rows.push(row);return rows;}
async function importCSV(file){return DataFiles.importCSV(file);}
paintIcons();updateGenres();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>goto(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();goto('discover');};$('#filter-toggle').onclick=()=>{$('#filter-toggle').classList.toggle('open');$('#filters').hidden=!$('#filter-toggle').classList.contains('open');persist();};Object.entries({'genre-filter':'genre','year-min':'min','year-max':'max','duration-filter':'duration','provider-filter':'provider'}).forEach(([id,key])=>$('#'+id).oninput=e=>{filter[key]=e.target.value;gridLimit=24;const count=Object.values(filter).filter(Boolean).length;$('#filter-count').textContent=count?`· ${count}`:'';persist();render();scheduleTMDBLoad();});$('#reset-filters').onclick=resetFilters;$('#import-button').onclick=()=>$('#csv-input').click();$('#csv-input').onchange=e=>importCSV(e.target.files[0]);$('#help-button').onclick=()=>$('#help').showModal();$('#start-button').onclick=()=>$('#help').close();document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});document.addEventListener('keydown',e=>{if(page!=='discover'||$('dialog[open]')||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)||busy)return;const mapping={ArrowRight:'like',ArrowLeft:'dislike',ArrowUp:'watch',ArrowDown:'uninterested'};if(mapping[e.key]&&$('.movie-card')){e.preventDefault();choose(Number($('.movie-card').dataset.id),mapping[e.key],true);}});DataFiles.applyPreferences();render();if(!storageOK)toast('Salvataggio locale non disponibile in questo browser.');

function updateGenres(){const select=$('#genre-filter');const value=select.value;const seen=new Set([...select.options].map(o=>o.value));for(const g of [...new Set([...movies.flatMap(m=>m.genres),...Object.values(TMDB.genreNames)])].sort())if(!seen.has(g))select.add(new Option(g,g));select.value=value;}
function updateCatalogStatus(){
  $('#catalog-total').textContent=`${movies.length.toLocaleString('it-IT')} film disponibili`;
  $('#tmdb-button').textContent=TMDB.connected?'TMDB collegato':'Collega TMDB';
  $('#provider-filter').disabled=!TMDB.connected;
  $('#filters > p').textContent=TMDB.connected?'Disponibilità in abbonamento in Italia da TMDB. Per noleggio e acquisto consulta JustWatch.':'Collega TMDB per filtrare per abbonamento e caricare nuovi film con questi filtri.';
  const activeFilters=Object.values(filter).filter(Boolean).length;$('#filter-count').textContent=activeFilters?`· ${activeFilters}`:'';
  const status=$('#catalog-status');
  status.innerHTML=`<span>${TMDB.connected?'● TMDB collegato':'● Catalogo ampliato'} · ${movies.length.toLocaleString('it-IT')} film</span>${TMDB.loading?'<span>Caricamento…</span>':TMDB.connected&&TMDB.hasMore(filter)?'<button id="load-movies">Carica altri film ↗︎</button>':!TMDB.connected?'<button id="connect-inline">Aggiungi nuovi film con TMDB ↗︎</button>':''}${TMDB.error?`<p class="catalog-error">${esc(TMDB.error)} <button id="retry-movies">Riprova</button></p>`:''}`;
  if($('#load-movies'))$('#load-movies').onclick=()=>TMDB.more({...filter});
  if($('#connect-inline'))$('#connect-inline').onclick=openTMDB;
  if($('#retry-movies'))$('#retry-movies').onclick=()=>TMDB.more({...filter});
}
function openTMDB(){
  $('#tmdb-message').textContent=TMDB.connected?'Connessione attiva in questa sessione. Puoi sostituire la credenziale o scollegare.':'';
  $('#tmdb-disconnect').hidden=!TMDB.connected;
  $('#tmdb-token').value='';$('#tmdb-dialog').showModal();
}
let tmdbFilterTimer;
function maybeLoadMore(){if(TMDB.connected&&!TMDB.loading&&!TMDB.error&&TMDB.hasMore(filter)&&movies.filter(m=>m.source==='tmdb'&&!state.choices[m.id]&&passes(m)).length<5)setTimeout(()=>TMDB.more({...filter}),0);}
function scheduleTMDBLoad(){clearTimeout(tmdbFilterTimer);if(TMDB.connected)tmdbFilterTimer=setTimeout(()=>TMDB.more({...filter}),500);}
let catalogRefreshTimer;
function onTMDBChange(){
  if(busy||$('.movie-card.dragging')){clearTimeout(catalogRefreshTimer);catalogRefreshTimer=setTimeout(onTMDBChange,100);return;}
  updateGenres();render();
  if($('#details').open){const id=Number($('#details-content [data-detail-action]')?.dataset.movieId);if(id)details(id);}
}
$('#tmdb-button').onclick=openTMDB;
$('#tmdb-form').onsubmit=async e=>{
  e.preventDefault();const button=$('#tmdb-connect');button.disabled=true;button.textContent='Connessione…';$('#tmdb-message').textContent='';
  try{await TMDB.connect($('#tmdb-token').value);$('#tmdb-token').value='';$('#tmdb-dialog').close();toast('TMDB collegato: carico nuovi film.');await TMDB.more({...filter});}
  catch(e){$('#tmdb-message').textContent=e.message;}
  finally{button.disabled=false;button.textContent='Collega e carica film →';}
};
$('#tmdb-disconnect').onclick=()=>{TMDB.disconnect();filter.provider='';$('#provider-filter').value='';$('#tmdb-dialog').close();render();toast('TMDB scollegato. Le tue scelte restano salvate.');};
updateCatalogStatus();if(TMDB.connected)TMDB.more({...filter});

$('#backup-input').onchange=e=>DataFiles.readBackup(e.target.files[0]);
$('#backup-merge').onclick=()=>DataFiles.restore('merge');
$('#backup-replace').onclick=()=>DataFiles.restore('replace');
$('#backup-cancel').onclick=()=>{$('#backup-dialog').close();DataFiles.pending=null;};
$('#backup-dialog').addEventListener('close',()=>DataFiles.pending=null);

